void readSingleImageFrame(MagickCore::Image *image, MagickCore::ExceptionInfo *exceptionInfo) {
    if (image && image->scene < image->number_scenes - 1) {
        MagickCore::Image *next = image->next;
        while (next) {
            MagickCore::Image *temp = next->next;
            next = DestroyImage(next);
            next = temp;
        }
        image->next = (MagickCore::Image *) NULL;
        image->number_scenes = 1;
    }

    if (image) {
        ReplaceImage(&image, image);
    }

    if (GetExceptionType(exceptionInfo) == UndefinedException && !image) {
        exceptionInfo = DestroyExceptionInfo(exceptionInfo);
        if (!quiet_mode) {
            (void) fprintf(stderr, "Warning: Image read failed.\n");
        }
    }

    if (image && exceptionInfo && (exceptionInfo->severity != NoSeverities)) {
        MagickCore::Image *imageException = CloneImage(image, 0, 0, MagickTrue, (ExceptionInfo *) NULL);
        if (imageException) {
            ThrowImageException(imageException, exceptionInfo);
            imageException = DestroyImage(imageException);
        }
    }
}

void readSingleImageFrame(MagickCore::Image *image, MagickCore::ExceptionInfo *exceptionInfo) {
    if (image != (MagickCore::Image *) NULL) {
        if (image->scene != 0 || image->next != (MagickCore::Image *) NULL) {
            /* Destroy extra frames */
            MagickCore::Image *p = image->next;
            while (p != (MagickCore::Image *) NULL) {
                MagickCore::Image *next = p->next;
                p = DestroyImage(p);
                p = next;
            }
            image->scene = 0;
        }
        /* Replace current image with provided one */
        image = ReplaceImageInList(&image);
    }

    if ((exceptionInfo->severity != UndefinedException) && (image == (MagickCore::Image *) NULL)) {
        exceptionInfo = DestroyExceptionInfo(exceptionInfo);
        if (!Is QuietMode) {
            (void) ThrowMagickException(exceptionInfo, GetMagickModule(), WarningError, "ImageNotAvailable", "Unable to read image");
        }
    }

    image_exception(image, exceptionInfo);
}

